import{_ as o,o as e,c as a,ai as r}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"Exporting Your Data","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/export.md","filePath":"en/guide/export.md"}'),i={name:"en/guide/export.md"};function s(n,t,d,l,h,u){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="exporting-your-data" tabindex="-1">Exporting Your Data <a class="header-anchor" href="#exporting-your-data" aria-label="Permalink to &quot;Exporting Your Data&quot;">​</a></h1><p>LLMxRay generates rich data — benchmarks, sessions, conversations, tool definitions, and system reports. Every piece of data you create is exportable. Your data stays local until you choose to share it.</p><h2 id="what-can-be-exported" tabindex="-1">What Can Be Exported <a class="header-anchor" href="#what-can-be-exported" aria-label="Permalink to &quot;What Can Be Exported&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Formats</th><th>What&#39;s Included</th></tr></thead><tbody><tr><td>Compare</td><td>JSON, Markdown, Share</td><td>Prompts, outputs, metrics, Token Tax</td></tr><tr><td>Benchmark</td><td>JSON, CSV, Markdown</td><td>Questions, answers, accuracy, per-category results</td></tr><tr><td>Session</td><td>JSON, Markdown, Token CSV</td><td>Prompt, response, metrics, per-token latencies</td></tr><tr><td>Chat</td><td>JSON, Markdown, Text</td><td>Full conversation with timestamps</td></tr><tr><td>Tool Workshop</td><td>JSON</td><td>Tool definitions with implementations</td></tr><tr><td>System</td><td>JSON, Markdown</td><td>Hardware, Ollama status, models, storage</td></tr></tbody></table><h2 id="export-formats" tabindex="-1">Export Formats <a class="header-anchor" href="#export-formats" aria-label="Permalink to &quot;Export Formats&quot;">​</a></h2><ul><li><strong>JSON</strong> — Full structured data. Use for scripts, analysis, reimporting.</li><li><strong>CSV</strong> — Flat tabular data. Open in Excel, Google Sheets, or pandas.</li><li><strong>Markdown</strong> — Formatted reports. Paste into docs, blogs, or GitHub.</li><li><strong>JSONL</strong> — Line-delimited JSON for training data export.</li><li><strong>Text</strong> — Plain conversation transcripts.</li></ul><h2 id="how-to-export" tabindex="-1">How to Export <a class="header-anchor" href="#how-to-export" aria-label="Permalink to &quot;How to Export&quot;">​</a></h2><ol><li>Look for the <strong>Export</strong> button (download icon) on any results page.</li><li>Click to see available formats.</li><li>Select a format — the file downloads immediately.</li><li>For sharing: choose <strong>&quot;Share to GitHub Discussions&quot;</strong> to post findings.</li></ol><h2 id="sharing-to-github-discussions" tabindex="-1">Sharing to GitHub Discussions <a class="header-anchor" href="#sharing-to-github-discussions" aria-label="Permalink to &quot;Sharing to GitHub Discussions&quot;">​</a></h2><p>Available on the Compare and Benchmark pages. The Share feature pre-fills a GitHub Discussion post with your formatted report. You add your own commentary and review everything before posting. Nothing is sent without your explicit action.</p><ol><li>Click <strong>&quot;Share to GitHub Discussions&quot;</strong> in the Export menu.</li><li>A dialog opens with a preview of the markdown report.</li><li>Add your commentary — describe what you discovered.</li><li>Click <strong>&quot;Open GitHub Discussions&quot;</strong> to be redirected to GitHub with the report pre-filled.</li><li>You review and submit the post yourself — nothing is posted without your consent.</li></ol><h2 id="data-privacy" tabindex="-1">Data Privacy <a class="header-anchor" href="#data-privacy" aria-label="Permalink to &quot;Data Privacy&quot;">​</a></h2><blockquote><p>Your data never leaves your machine unless you choose to share it. All exports download to your local filesystem. The Share feature opens a GitHub URL — you control what gets posted.</p></blockquote>',13)])])}const m=o(i,[["render",s]]);export{p as __pageData,m as default};
